      (* [comment removed for export] *)
      Ltac cut_prep MI PSI TR :=
        prep; seg_in MI PSI;
        pose proof PSI as (PE & PD & PEC & PM & PIT & PT & PCH & TNN);
        try (pose proof TR as (Ta0 & Tt3 & Tt1 & Tt2 & Ta1 & Tt5 & Tt4 & Tt6 & Tra)).
      Ltac uspa := lazymatch goal with U : bv_unsigned spw = SPA |- _ => rewrite ?U | _ => idtac end.
      (* [comment removed for export] *)
      Ltac rebuild MI W MU WMc INVc FRc SPLc SZc SCc TCc BUFtac :=
        let sc' := fresh "sc'" in let Lsc' := fresh "Lsc'" in let SCR' := fresh "SCR'" in
        destruct (scratch_join _ _ _ SCc eq_refl) as (sc' & Lsc' & SCR');
        eapply (memI_seg2 _ _ _ _ _ _ _ W _ _ sc' _ MI MU WMc INVc);
        [ apply segW2_of_segW; unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; uspa; unfold pa, ta in *; lia|]); apply Forall_nil
        | eapply (seg_stk _ _ _ _ _ _ _ W MI MU WMc); unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; uspa; unfold pa, ta in *; lia|]); apply Forall_nil
        | neexists 9; split; [exact FRc| SPLc]
        | exact SZc | exact SCR' | exact TCc
        | BUFtac ].

      (* [comment removed for export] *)
      Ltac a8tot := try (lazymatch goal with A : a8I _ _ _ _ _ |- _ => pose proof A as (_ & _ & _ & ?T0 & _) end).
      (* [comment removed for export] *)
      Ltac arith_goal := lazymatch goal with
                         | |- (_ <= _ <= _)%Z => idtac | |- (_ <= _ < _)%Z => idtac | |- (_ < _ <= _)%Z => idtac | |- (_ < _ < _)%Z => idtac
                         | |- (_ <= _)%Z => idtac | |- (_ < _)%Z => idtac | |- (_ >= _)%Z => idtac | |- (_ > _)%Z => idtac
                         | |- @eq Z _ _ => idtac | |- not (@eq Z _ _) => idtac end.
      Ltac kx := first [ lazymatch goal with |- pecore ?rr _ _ _ _ => match goal with P : pecore rr _ _ _ _ |- _ => exact P end end
                       | eassumption
                       | reg_chain
                       | unfold TREGS, SREGS; repeat split; regeq
                       | arith_goal; a8tot; unfold q0, vs_n in *; olia ].

