      (* [comment removed for export] *)
      Ltac rebuild2 MI W MU WMc INVc FRc SZc SCc TCc :=
        let sc' := fresh "sc'" in let Lsc' := fresh "Lsc'" in let SCR' := fresh "SCR'" in
        destruct (scratch_join _ _ _ SCc eq_refl) as (sc' & Lsc' & SCR');
        eapply (memI_seg2 _ _ _ _ _ _ _ W _ _ sc' _ MI MU WMc INVc);
        [ apply segW2_of_segW; unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; uspa; unfold pa, ta in *; lia|]); apply Forall_nil
        | eapply (seg_stk _ _ _ _ _ _ _ W MI MU WMc); unfold segW_ok; repeat (apply Forall_cons; [cbn [fst snd]; uspa; unfold pa, ta in *; lia|]); apply Forall_nil
        | neexists 9; split; [exact FRc| ]
        | exact SZc | exact SCR' | exact TCc
        | ].
      Ltac rebuildM MI spl' :=
        lazymatch goal with
        | MU : munch ?W _ ?mq, FRc : rw_cells asegs ?mq (bv_unsigned spw) _, SCc : rw_cells asegs ?mq (bv_unsigned a0 + 160) _,
          TCc : rw_cells asegs ?mq (bv_unsigned a2) _, SZc : rw_cells asegs ?mq (ff + 288) _, WMc : wmono asegs _ ?mq, INVc : mem_inv asegs ?mq |- _ =>
            lazymatch type of MI with memI _ ?stq ?psq _ _ _ =>
              eassert (MI' : memI mq stq psq _ _ spl'); [rebuild2 MI W MU WMc INVc FRc SZc SCc TCc|]
            end
        end.
      Ltac spl_true := intros _; unfold pespill; repeat split; reflexivity.
      Ltac buf_same BUF := lazymatch goal with MU : munch _ _ ?mq, WMc : wmono asegs _ ?mq |- _ =>
                             eapply buf_keep; [exact BUF| exact MU| exact WMc| cbn; uspa; unfold pa, ta in *; lia] end.
      (* [comment removed for export] *)
      Ltac reg_ne0 := lazymatch goal with |- bv_unsigned (?f ?rr) <> 0 => match goal with Hq : f rr = _ |- _ => rewrite Hq; rewrite unsigned_lit by lia; lia end end.
      Ltac reg_ge2 := lazymatch goal with |- 2 <= bv_unsigned (?f ?rr) => match goal with Hq : f rr = _ |- _ => rewrite Hq; rewrite unsigned_lit by lia; lia end end.
      Ltac rra_site := first [ left; eassumption | right; split; [eassumption| reflexivity] ].
      (* [comment removed for export] *)
      Ltac go_fail MIx p' :=
        eapply (tail_failA _ _ _ _ _ _ _ _ _ _ _ _ p');
        [ eassumption | eassumption | eapply mp3; eassumption | exact MIx | eassumption | eassumption | kx | kx
        | eassumption | kx | kx | kx | kx | kx | reg_ne0 | reg_ge2 | rra_site ].
      Ltac go_msusp MIx p' :=
        eapply (tail_msuspA _ _ _ _ _ _ _ _ _ _ _ _ p');
        [ eassumption | eassumption | eapply mp3; eassumption | exact MIx | eassumption | eassumption | kx | kx
        | eassumption | kx | kx | kx | kx | kx | eassumption
        | first [left; reflexivity| right; left; reflexivity| right; right; left; reflexivity| right; right; right; reflexivity] ].

